window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/humanas_2022.js"]=[{"title":"O saber tradicional interpreta o ambiente","steps":["As pedras de sal são associadas aos meses futuros numa prática religiosa tradicional.","O costume expressa a atenção do sertanejo à chuva e à seca no ambiente da Caatinga.","D identifica essa intimidade ambiental. O trecho descreve um saber cultural, não comprova eficácia científica de previsão de seis meses."],"alternatives":{"A":"A devoção participa do costume, mas aceitar destinos não resume a leitura das condições ambientais.","B":"O texto não explica a pobreza como aceitação de acasos naturais.","C":"Não se está identificando a aptidão agrícola de diferentes terrenos.","D":"O ritual expressa uma maneira cultural de interpretar sinais ambientais da Caatinga.","E":"A observação é do sal e da chuva, não da identificação de arbustos."},"takeaway":"Diferencie o significado cultural de uma prática da comprovação científica de sua eficácia.","key":"humanas:H449","area":"humanas","year":2022,"number":46,"answer":"D","subject":"Geografia","topic":"Climatologia e biomas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A linguagem torna possível uma vida em comum","steps":["Arendt distingue o homem singular dos homens no plural, que convivem e agem.","O discurso permite discutir experiências e tornar-se inteligível aos outros.","E sintetiza a construção da sociabilidade, e não somente uma competência técnica individual."],"alternatives":{"A":"Entender cultura pode envolver linguagem, mas o argumento central trata da convivência política.","B":"A autora não descreve um aumento de criatividade como resultado principal.","C":"O contraste privilegia a pluralidade, não a percepção isolada de si.","D":"O desenvolvimento de técnicas não é a função discutida do discurso.","E":"Falar e compreender-se sustentam relações, ação e significados compartilhados."},"takeaway":"Em Arendt, procure os vínculos entre linguagem, pluralidade e ação no espaço comum.","key":"humanas:H701","area":"humanas","year":2022,"number":47,"answer":"E","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A abolição não elimina automaticamente o racismo","steps":["A narradora relaciona violência policial contra um homem negro à persistência do regime da chibata.","O contraste com a escravidão já extinta denuncia a permanência de relações racializadas de poder.","A identifica racismo estrutural; a menção à grafia não transforma o tema numa avaliação escolar da autora."],"alternatives":{"A":"A violência e a atribuição de culpa às pessoas negras revelam a persistência do racismo nas relações sociais.","B":"O episódio não trata de ausência de emprego como problema principal.","C":"A distribuição de renda não é o fato específico denunciado pela narradora.","D":"A leitura de um jornal não indica que o problema central seja falta de informação.","E":"A conservação da grafia não autoriza substituir a denúncia racial por juízo sobre escolarização."},"takeaway":"Leia o conteúdo da denúncia sem deixar que preconceitos linguísticos desviem o foco.","key":"humanas:H787","area":"humanas","year":2022,"number":48,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Impermeabilização redistribui a água","steps":["O esquema compara cobertura natural e graus crescentes de superfície impermeável.","O escoamento superficial sobe de 10% para 55%, enquanto infiltração e percolação diminuem.","As parcelas pertencem ao ciclo hidrológico, diretamente alterado pela urbanização: B."],"alternatives":{"A":"O gráfico não mede uma alteração imediata da altitude do terreno.","B":"Infiltração, percolação, evapotranspiração e escoamento são componentes do ciclo da água.","C":"O clima pode sofrer efeitos urbanos, mas o efeito representado é a circulação da água.","D":"Cobrir o solo com construções não modifica imediatamente a tectônica de placas.","E":"A imagem não descreve transformação imediata da estrutura das rochas."},"takeaway":"A superfície impermeável não faz a água desaparecer: muda os caminhos e tempos de sua circulação.","key":"humanas:H579","area":"humanas","year":2022,"number":49,"answer":"B","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O progresso tem um custo humano ocultado","steps":["A ferrovia e o hospital aparecem como símbolos de modernização.","O narrador contrasta esse progresso com doenças, mortes e anonimato dos trabalhadores.","E identifica a contradição entre desenvolvimento e respeito à vida de quem constrói a obra."],"alternatives":{"A":"Fauna e engenharia ambiental não são o centro da crítica às mortes descritas.","B":"O contraste principal não é entre origem da máquina e domínio da floresta.","C":"O trecho enfatiza trabalhadores, sem restringir as vítimas a nativos nem o financiamento ao Estado.","D":"Não se narra uma disputa entre medicamentos industriais e fitoterapia.","E":"A modernização convive com exploração e invisibilidade dos trabalhadores adoecidos."},"takeaway":"Nos relatos de progresso, procure quem recebe benefícios e quem suporta custos sociais.","key":"humanas:H083","area":"humanas","year":2022,"number":50,"answer":"E","subject":"História do Brasil","topic":"Primeira República","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A produção se articula além de um único território","steps":["A economia descrita depende de informação e redes empresariais globais.","Etapas e agentes podem conectar-se em lugares distintos por fluxos materiais e informacionais.","E expressa a desterritorialização da produção, sem significar que as atividades deixem de ocorrer em lugares concretos."],"alternatives":{"A":"Produção em série já existia antes da economia informacional global.","B":"Redes flexíveis não exigem necessariamente ampliar estoques.","C":"O texto não demonstra enfraquecimento geral de cartéis empresariais.","D":"Padronização não é o resultado espacial específico pedido.","E":"A organização em redes permite dispersar e articular etapas produtivas entre territórios."},"takeaway":"Desterritorialização não é ausência de localização: é reorganização de vínculos e controles espaciais.","key":"humanas:H423","area":"humanas","year":2022,"number":51,"answer":"E","subject":"Geografia","topic":"Industrialização, trabalho e redes","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O rural abastece a vida urbana","steps":["A canção contrapõe o gigante de tijolo e cimento ao trabalho no arroz, no milho e no cacau.","Os nomes dos trabalhadores tornam visível a origem dos alimentos consumidos.","D valoriza a produção alimentar rural como parte indispensável da relação com a cidade."],"alternatives":{"A":"O texto destaca trabalho agrícola e alimentos, não formação de mão de obra especializada.","B":"Inovação tecnológica não é o eixo dos versos sobre sementes e colheitas.","C":"Biodiversidade é importante, mas não é a função rural ressaltada na letra.","D":"A comida na mesa urbana depende da produção realizada no campo.","E":"A garantia de moradia não é a contribuição rural enfatizada pela canção."},"takeaway":"Campo e cidade se relacionam por fluxos: identifique qual fluxo o texto valoriza.","key":"humanas:H308","area":"humanas","year":2022,"number":52,"answer":"D","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Leitoras também se tornam autoras e editoras","steps":["Folhetins encontram um público feminino em ampliação.","A participação avança da leitura para a produção e direção de periódicos.","A reúne essas novas práticas culturais; não se descreve apenas o crescimento de empresas editoriais."],"alternatives":{"A":"Ler, escrever e editar publicações ampliam as formas de participação cultural das mulheres.","B":"A mudança de hábitos masculinos não é o objeto específico do relato.","C":"As publicações não são caracterizadas como especialmente juvenis.","D":"Manuais pedagógicos não constituem o gênero central apresentado.","E":"A emergência de uma imprensa feminina não se reduz ao número de editoras comerciais."},"takeaway":"Participar da cultura envolve tanto consumir obras quanto produzir e organizar sua circulação.","key":"humanas:H062","area":"humanas","year":2022,"number":53,"answer":"A","subject":"História do Brasil","topic":"Império e independência","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Lutas trabalhistas integram a crise do Império","steps":["Os caixeiros se associam e reivindicam mediação pública para seus direitos.","Nos anos 1880, atuam junto a republicanos e abolicionistas no espaço político.","E situa essa mobilização na contestação da ordem monárquica, sem supor sindicatos já plenamente consolidados."],"alternatives":{"A":"A reivindicação de direitos contesta, em vez de simplesmente manter, o poder patronal.","B":"A aproximação com republicanos e abolicionistas não significa abandono geral de ideias liberais.","C":"O trecho destaca associação e ação política, não fortalecimento de contratos específicos.","D":"Associações pioneiras não equivalem à consolidação de estruturas sindicais posteriores.","E":"A mobilização se aproxima de movimentos que confrontavam pilares da ordem imperial."},"takeaway":"Contextualize uma categoria de trabalhadores na conjuntura política, sem projetar instituições posteriores.","key":"humanas:H038","area":"humanas","year":2022,"number":54,"answer":"E","subject":"História do Brasil","topic":"Escravidão, abolição e resistências","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Irrigar sem drenar favorece acúmulo de sais","steps":["A água leva sais ao solo e evapora rapidamente no ambiente semiárido.","Se a drenagem é insuficiente, os sais permanecem e se concentram próximo à superfície.","B identifica a prática que intensifica a salinização descrita."],"alternatives":{"A":"Florestamento com pinus não é o mecanismo de acúmulo de sais explicado.","B":"Irrigação sem drenagem adequada favorece a concentração de sais após a evaporação.","C":"Reduzir velocidade da água em açudes não é a causa agrícola direta apresentada.","D":"Assoreamento por desmatamento é outro processo ambiental, diferente de salinização.","E":"Fertilizantes orgânicos não são o fator específico que explica o processo descrito."},"takeaway":"Salinização depende do balanço entre entrada de sais, evaporação e remoção pela drenagem.","key":"humanas:H525","area":"humanas","year":2022,"number":55,"answer":"B","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A exclusão digital limita o acesso à educação","steps":["A charge mostra a dificuldade de obter sinal para estudar.","O texto explica que internet, equipamento e dados suficientes não estão disponíveis a todos.","A evidencia exclusão social expressa no acesso desigual aos meios digitais, não simples rejeição às tecnologias."],"alternatives":{"A":"A desigualdade de acesso compromete participação educacional e revela exclusão social.","B":"A expansão das redes não garante inclusão de todos os estudantes.","C":"A manifestação cultural não é a crítica central comum ao texto e à charge.","D":"A localização pode influenciar o sinal, mas o argumento aborda desigualdade de acesso mais ampla.","E":"O problema não é falta de valorização abstrata do conhecimento, mas condições materiais de estudar."},"takeaway":"Ter celular não equivale a ter infraestrutura suficiente para acompanhar aulas e produzir trabalhos.","key":"humanas:H844","area":"humanas","year":2022,"number":56,"answer":"A","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Do afastamento à vigilância minuciosa","steps":["Foucault contrapõe o exílio do leproso ao controle individualizado durante a peste.","Distribuir, observar e regular cada pessoa constitui uma tecnologia de poder.","A identifica a sociedade disciplinar, não a flexibilização das normas."],"alternatives":{"A":"Vigilância, repartição do espaço e treinamento dos corpos caracterizam a disciplina.","B":"O controle descrito torna as regras mais minuciosas, não mais flexíveis.","C":"A autoridade repressora é exercida por esses dispositivos, não banida.","D":"O texto analisa mecanismos de poder, não apenas condena moralmente a degradação.","E":"Há hierarquia, mas a burocracia estatal isolada não define todo o mecanismo disciplinar."},"takeaway":"Disciplina atua também organizando espaços, horários e comportamentos, não só aplicando castigos.","key":"humanas:H702","area":"humanas","year":2022,"number":57,"answer":"A","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Experiências religiosas criam lugares de peregrinação","steps":["As romarias transformam Juazeiro em referência de um espaço sagrado.","As práticas da beata e dos devotos ocorrem à margem da autorização episcopal inicial.","E associa criação de lugares místicos e catolicismo popular, sem exigir comprovar o milagre narrado."],"alternatives":{"A":"Os relatos não mostram abandono da espiritualidade; ela organiza as práticas.","B":"Não aparecem elementos judaizantes como fundamento das manifestações.","C":"Não se trata principalmente de expansão de fronteiras nem de cristianismo medieval.","D":"As práticas são católicas populares, não uma cerimônia ecumênica entre religiões.","E":"Romarias sacralizam lugares e a devoção narrada expressa experiências do catolicismo popular."},"takeaway":"Analise a função social de uma crença sem precisar julgá-la como verdadeira ou falsa.","key":"humanas:H788","area":"humanas","year":2022,"number":58,"answer":"E","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A compra pública cria um mercado para a agricultura familiar","steps":["O programa compra alimentos de produtores familiares e grupos enquadrados.","Essa demanda institucional oferece um canal de venda vinculado à segurança alimentar.","C identifica a comercialização assegurada pelo programa, sem significar compra ilimitada de toda produção."],"alternatives":{"A":"A política é de aquisição de produtos, não de introdução obrigatória de uma tecnologia.","B":"Comprar alimentos não realiza por si uma redistribuição da propriedade da terra.","C":"O mercado institucional cria uma demanda direcionada aos pequenos produtores elegíveis.","D":"O texto não diz que todo custo de transporte seja eliminado.","E":"As vendas se destinam a compras públicas, não à negociação em bolsa."},"takeaway":"Política de mercado pode apoiar agricultores sem se confundir com crédito, tecnologia ou reforma fundiária.","key":"humanas:H309","area":"humanas","year":2022,"number":59,"answer":"C","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Incentivar o outro cria reciprocidade","steps":["A recompensa é paga a conhecidos quando o participante aumenta sua atividade.","O desenho do experimento mobiliza relações de incentivo mútuo na comunidade.","B destaca a função social e a reciprocidade mediadas pelo celular, sem concluir que qualquer vigilância digital seja benéfica."],"alternatives":{"A":"O foco não é entretenimento em redes, mas uma intervenção sobre atividade física.","B":"Os vínculos entre participantes fazem o incentivo circular e estimulam reciprocidade.","C":"Não se trata de transformar o desenvolvedor do aplicativo em usuário final.","D":"A compra de bens industrializados não é o objetivo do experimento.","E":"O resultado medido é atividade física, não aprendizagem por ferramentas educacionais."},"takeaway":"O efeito de uma tecnologia depende do desenho de uso e das relações sociais que ela mobiliza.","key":"humanas:H845","area":"humanas","year":2022,"number":60,"answer":"B","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A automação pode eliminar funções profissionais","steps":["O texto descreve transposição automatizada de vozes para outros idiomas.","A mesma tecnologia que facilita a produção pode reduzir a demanda por trabalhadores da dublagem.","E identifica desemprego estrutural, ligado à mudança produtiva, não apenas a uma oscilação temporária de vendas."],"alternatives":{"A":"A tecnologia não é apresentada como medida de proteção da economia nacional.","B":"O texto não atribui à inovação uma valorização das tradições culturais.","C":"Menos oportunidades na ocupação não equivale a redução da formação acadêmica.","D":"A produção artística pode continuar mesmo com substituição de funções humanas.","E":"A reorganização tecnológica pode tornar postos e qualificações anteriores menos demandados."},"takeaway":"Desemprego estrutural decorre de transformações da estrutura produtiva, não somente de uma crise conjuntural.","key":"humanas:H761","area":"humanas","year":2022,"number":61,"answer":"E","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A tarifa externa é uma regra compartilhada","steps":["A TEC regula a entrada de produtos de fora do bloco.","Uma alteração exige negociação porque os membros compartilham a política tarifária externa da união aduaneira.","C explica a necessidade de acordo; Mercosul não significa moeda única ou leis trabalhistas idênticas."],"alternatives":{"A":"A negociação descrita trata de tarifas comerciais, não de circulação financeira.","B":"O bloco não exige uma política monetária única nem uma moeda comum.","C":"A tarifa externa comum é uma característica de sua organização como união aduaneira.","D":"Dependência agrícola não explica institucionalmente o compartilhamento da tarifa.","E":"A equivalência das leis trabalhistas não é a regra que exige esse acordo."},"takeaway":"Diferencie livre-comércio interno, união aduaneira e união monetária.","key":"humanas:H361","area":"humanas","year":2022,"number":62,"answer":"C","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A caridade narrada também envolve governo","steps":["A fonte pode representar a ajuda como piedade individual.","A análise histórica recoloca o socorro à fome no campo da gestão pública.","B associa o dever à realeza e à concepção de governo da monarquia cristã, sem projetar sobre o século VI o Estado moderno."],"alternatives":{"A":"A obrigação específica não é atribuída apenas à proteção do camponês livre pela nobreza.","B":"O dever público de socorro integra a legitimidade e as responsabilidades da realeza cristã.","C":"Mosteiros podiam prestar auxílio, mas não substituem a jurisdição de governo pedida.","D":"A atuação de clérigos não é a explicação principal para o dever de gestão pública.","E":"Corporações de ofício não são a autoridade central do contexto apresentado."},"takeaway":"Diferencie a forma como uma fonte elogia um indivíduo da função política que sua ação desempenha.","key":"humanas:H171","area":"humanas","year":2022,"number":63,"answer":"B","subject":"História Geral","topic":"Idade Média","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A rocha vulcânica se transforma em solo","steps":["Forças internas originam materiais vulcânicos.","Intemperismo e outros processos externos alteram esses materiais e participam da formação de solos.","A combina os dois grupos de forças em solos vulcânicos, que podem favorecer cultivo e ocupação quando outras condições permitem."],"alternatives":{"A":"A origem vulcânica e a alteração superficial articulam processos endógenos e exógenos.","B":"Dorsais são estruturas submarinas e não a forma favorável de ocupação pedida.","C":"Escarpas podem dificultar a ocupação e não expressam o mesmo resultado pedológico.","D":"Laterização não exige o aporte vulcânico que articula as forças ressaltadas.","E":"Dobramentos são sobretudo resultados tectônicos, sem indicar a formação de solo pelo processo externo."},"takeaway":"Uma paisagem resulta da interação entre construção interna e transformação externa, não de uma força isolada.","key":"humanas:H526","area":"humanas","year":2022,"number":64,"answer":"A","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A espiral representa escalada de violência","steps":["A imagem alterna tensão, agressão e reconciliação.","A repetição se estreita até o ápice marcado pela morte.","No contexto de violência de gênero, esse ápice é feminicídio, B. A figura não torna a morte inevitável nem responsabiliza a vítima por permanecer na relação."],"alternatives":{"A":"Cancelamento é outra dinâmica social, não a morte no ciclo de violência mostrado.","B":"A morte violenta de mulher por razões de gênero corresponde ao feminicídio indicado.","C":"Negacionismo não nomeia a conduta que culmina em morte na ilustração.","D":"A sequência de controle e agressões não é um acidente involuntário.","E":"Defesa da honra não é justificativa legítima para violência e não descreve o conceito pedido."},"takeaway":"Reconciliações não anulam agressões; a imagem alerta para a repetição e possível agravamento do ciclo.","key":"humanas:H736","area":"humanas","year":2022,"number":65,"answer":"B","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O currículo pode reproduzir ou enfrentar desigualdade","steps":["Cayru usa uma alegada incapacidade feminina para restringir a aprendizagem.","Santo Amaro contesta o costume e defende acesso aos mesmos conhecimentos.","C contrapõe controle/dominação dos corpos à igualdade humana, sem aceitar como fato a inferioridade atribuída às meninas."],"alternatives":{"A":"O primeiro discurso restringe, não promove liberdade de gênero.","B":"A ordem está invertida: o primeiro texto impõe limites, o segundo enfrenta a restrição.","C":"Limitar educação por gênero disciplina papéis sociais; defender currículo igual contesta essa hierarquia.","D":"O primeiro orador não amplia oportunidades, e o segundo não busca restrição profissional.","E":"A defesa do segundo texto é de igualdade educacional, não especificamente de participação política."},"takeaway":"Identifique a ordem dos pontos de vista antes de avaliar alternativas com respectivamente.","key":"humanas:H063","area":"humanas","year":2022,"number":66,"answer":"C","subject":"História do Brasil","topic":"Império e independência","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O movimento exige efetivar um direito já previsto","steps":["A ocupação reivindica transformar terreno abandonado em moradia.","O texto relaciona a demanda ao direito social previsto na Constituição.","D identifica a estratégia de efetivar o preceito constitucional, não de incentivar valorização especulativa."],"alternatives":{"A":"A demanda por atuação pública não tem como finalidade simplesmente enfraquecer o Estado.","B":"Não se descreve principalmente uma rede de produção e consumo solidários.","C":"O objetivo é acesso à moradia, não controle geral da propriedade estatal.","D":"O movimento procura tornar concreto o direito constitucional à moradia.","E":"Usar o terreno para habitação popular contrasta com mantê-lo como ativo especulativo."},"takeaway":"A existência jurídica de um direito não garante sua realização: movimentos podem reivindicar sua efetividade.","key":"humanas:H395","area":"humanas","year":2022,"number":67,"answer":"D","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A leitura estratégica associa recursos e influência","steps":["O mapa destaca reservas energéticas e diversidade biológica.","O texto interpreta regiões como pouco integradas às normas promovidas pelos EUA e instituições econômicas.","D identifica a ampliação de influência econômica, não uma iniciativa neutra de preservação ambiental."],"alternatives":{"A":"O interesse estratégico descrito não é uma distribuição igualitária de inovação.","B":"O projeto é de integração a normas hegemônicas, não de autonomia financeira dessas regiões.","C":"O tema é controle e recursos, não intercâmbio cultural como finalidade principal.","D":"Recursos e integração às regras econômicas sustentam a estratégia de ampliar influência.","E":"Destacar recursos naturais no mapa não prova compromisso com sua conservação."},"takeaway":"Um mapa de recursos pode servir a um projeto geopolítico: pergunte quem o produz e com qual finalidade.","key":"humanas:H580","area":"humanas","year":2022,"number":68,"answer":"D","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um pertencimento nacional é usado para reivindicar território","steps":["Putin apresenta a Crimeia como parte histórica e afetiva da Rússia.","O argumento aproxima identidade nacional e unidade sob uma mesma autoridade estatal.","A é a justificativa nacionalista reconstruída pelo item; identificá-la não legitima juridicamente a anexação nem afirma que idioma imponha soberania."],"alternatives":{"A":"A alternativa traduz o apelo à unidade político-territorial de populações ligadas por identidade comum.","B":"O discurso não é uma análise da acomodação do imperialismo soviético às potências vizinhas.","C":"A incapacidade de organismos internacionais não é o argumento citado.","D":"Livre circulação em blocos econômicos não é a razão alegada para anexar a península.","E":"Não se fundamenta a reivindicação na expulsão de forças navais ocidentais."},"takeaway":"Descrever uma justificativa política não significa endossar sua validade jurídica ou moral.","key":"humanas:H362","area":"humanas","year":2022,"number":69,"answer":"A","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Desigualdades se cruzam, não apenas se somam isoladamente","steps":["A pobreza varia entre arranjos familiares e grupos raciais.","Mulheres pretas ou pardas sem cônjuge com filhos pequenos têm proporção de pobreza maior que mulheres brancas no mesmo arranjo.","A evidencia o cruzamento de raça e gênero, no quadro social apresentado."],"alternatives":{"A":"A combinação de gênero e raça altera a exposição à pobreza e à discriminação.","B":"Etnia e habitação não são as duas categorias comparadas pelo recorte do gráfico.","C":"O limite de idade dos filhos não faz de idade e casamento a comparação principal.","D":"O quadro não diferencia profissões nem orientações sexuais.","E":"Não há recorte por escolaridade que sustente essa alternativa."},"takeaway":"Compare grupos que compartilham uma condição para enxergar como outro marcador modifica a desigualdade.","key":"humanas:H789","area":"humanas","year":2022,"number":70,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O poder democrático deve obedecer a regras","steps":["O texto define Estado de direito como limite ao arbítrio e sujeição de todos à lei.","Suprimir eleições elimina um mecanismo essencial de representação e controle democrático.","A é a violação entre as opções, não o exercício regular de competências legislativas."],"alternatives":{"A":"Suprimir eleições de representantes ataca garantias e mecanismos de limitação do poder.","B":"A atuação social de uma igreja não constitui, por si, violação do princípio descrito.","C":"Projetos sociais universitários não colocam autoridades acima da lei.","D":"Concentração de renda é grave questão social, mas não a violação institucional direta pedida.","E":"O Legislativo regulamentar trabalho no exercício constitucional não viola, por si, o Estado de direito."},"takeaway":"Diferencie injustiça social em geral da violação específica de uma garantia institucional perguntada.","key":"humanas:H820","area":"humanas","year":2022,"number":71,"answer":"A","subject":"Sociologia","topic":"Poder, Estado e política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ir e voltar diariamente é movimento pendular","steps":["Marcelo mantém sua moradia, mas viaja todos os dias para o emprego.","O deslocamento se repete entre lugares de residência e trabalho.","D identifica movimento pendular, sem exigir mudança permanente de domicílio."],"alternatives":{"A":"Fluxo de retorno geralmente envolve voltar ao lugar de origem depois de uma migração.","B":"Não se relata mudança de residência entre regiões, mas deslocamento cotidiano.","C":"O trajeto não depende de uma estação ou época específica do ano.","D":"A repetição diária de ida e volta entre casa e trabalho é pendularidade.","E":"O texto não descreve expulsão ou deslocamento compulsório da residência."},"takeaway":"Deslocamento diário não é necessariamente migração: observe se há mudança de domicílio.","key":"humanas:H490","area":"humanas","year":2022,"number":72,"answer":"D","subject":"Geografia","topic":"Demografia e migrações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A data organiza uma identidade de classe","steps":["A manifestação é descrita como ato político deliberado.","A festa busca produzir unidade política e cultural entre trabalhadores.","B identifica afirmação de identidade coletiva operária, e não uma comemoração nacional sem recorte de classe."],"alternatives":{"A":"O sentimento a construir é operário, não burguês.","B":"A comemoração comum ajuda a reconhecer pertencimento e interesses compartilhados de classe.","C":"A escala mencionada é internacional e de classe, não apenas nacional.","D":"Comunidade cívica é ampla e não destaca o sujeito específico do texto.","E":"O elemento decisivo é a construção política da classe, não uma tradição popular espontânea."},"takeaway":"Datas comemorativas podem ser instrumentos de organização e disputa de memória.","key":"humanas:H224","area":"humanas","year":2022,"number":73,"answer":"B","subject":"História Geral","topic":"Revolução Industrial e capitalismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Menos nuvens favorecem a radiação solar disponível","steps":["O mapa apresenta maior potencial em áreas com elevada incidência anual de radiação.","Nuvens refletem e absorvem parte da radiação que chegaria à superfície.","A reduzida nebulosidade, C, é o fator regional diretamente compatível com o potencial mostrado."],"alternatives":{"A":"Declividade pode importar num projeto local, mas não explica o padrão climático regional.","B":"Extensão longitudinal não determina diretamente a quantidade de nuvens ou radiação anual.","C":"Menor cobertura de nuvens favorece maior disponibilidade de energia solar na superfície.","D":"A região semiárida tem chuva irregular; não se trata de reduzir essa irregularidade.","E":"Continentalidade não é o fator direto de atenuação da radiação destacado."},"takeaway":"Latitude e nuvens atuam juntas: uma área muito ensolarada não precisa estar exatamente na linha do Equador.","key":"humanas:H581","area":"humanas","year":2022,"number":74,"answer":"C","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O rio integra memória, identidade e afeto","steps":["A narrativa de origem faz do rio parte da identidade Kambeba.","A aprendizagem com o pai liga experiência sensorial, saber e vínculo afetivo.","E reúne patrimônio cultural e afetivo, sem reduzir a relação a uma paisagem bonita ou a propriedade individual."],"alternatives":{"A":"Não é preciso tombamento ou musealização para existir o vínculo relatado.","B":"A cosmologia participa, mas o valor do rio vai além de uma herança exclusivamente religiosa.","C":"O rio é vivido e ensina, não é apenas cenário contemplativo.","D":"O vínculo é coletivo e duradouro, não uma riqueza individual passageira.","E":"Sabedoria compartilhada e memórias familiares tornam o rio referência cultural e afetiva."},"takeaway":"Patrimônio pode ser uma relação viva com um lugar, sem depender de estar guardado num museu.","key":"humanas:H790","area":"humanas","year":2022,"number":75,"answer":"E","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O trabalho constrói água armazenada e novos lugares","steps":["O relato acompanha trabalhadores na construção do açude.","A obra modifica o ambiente e se articula ao alojamento de famílias, descrito como embrião de cidade.","D identifica a formação social de novos espaços, não apenas uma operação técnica de distribuição da água."],"alternatives":{"A":"Engenheiros podem participar, mas o relato põe em primeiro plano os milhares de sertanejos.","B":"Não se narra a ampliação de fazendas por coronéis.","C":"A construção do açude é mais ampla que distribuir água já disponível.","D":"A obra e os alojamentos mostram trabalhadores produzindo uma nova configuração espacial.","E":"Redes de comércio e negociantes não são os protagonistas apresentados."},"takeaway":"Espaço geográfico é produzido por trabalho e relações sociais, não só por características naturais.","key":"humanas:H450","area":"humanas","year":2022,"number":76,"answer":"D","subject":"Geografia","topic":"Climatologia e biomas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A medicina é mobilizada para manter a exploração","steps":["As obras discutem administração da força de trabalho escravizada.","Reduzir doenças permite conservar trabalhadores e sustentar a produção colonial.","A relaciona o saber médico aos objetivos econômicos das elites; isso não transforma o cuidado instrumental em emancipação."],"alternatives":{"A":"Conservar a mão de obra escravizada atende à continuidade da produção e aos interesses senhoriais.","B":"A pesquisa naturalista de viajantes não é o objetivo administrativo central.","C":"O projeto busca gerir a escravidão, não suprimi-la.","D":"Os costumes dos povos nativos não explicam a finalidade dos manuais de gestão.","E":"A metrópole procura manter e desenvolver a colônia, não emancipá-la."},"takeaway":"Uma prática de cuidado pode ser incorporada a um sistema de exploração: avalie seu objetivo social.","key":"humanas:H039","area":"humanas","year":2022,"number":77,"answer":"A","subject":"História do Brasil","topic":"Escravidão, abolição e resistências","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A escala exige converter quilômetros em centímetros","steps":["O trecho entre Perth e os destroços representa cerca de 2 500 km no mapa.","Essa distância real vale 250 000 000 cm e corresponde a 2 cm desenhados.","Dividindo ambos por dois, a escala é 1 : 125 000 000, alternativa E."],"alternatives":{"A":"1 : 12 500 representa distância dez mil vezes menor que a calculada.","B":"1 : 125 000 não converte os quilômetros integralmente para centímetros.","C":"1 : 1 250 000 ainda fica cem vezes abaixo do denominador necessário.","D":"1 : 12 500 000 é dez vezes menor que a escala obtida.","E":"Dois centímetros para 250 milhões de centímetros resultam em 1 para 125 milhões."},"takeaway":"Em escala numérica, desenho e realidade precisam estar na mesma unidade antes de simplificar a razão.","key":"humanas:H559","area":"humanas","year":2022,"number":78,"answer":"E","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O objeto guarda práticas e habilidades de pessoas","steps":["A voz do tamborete recorda quem o fabricou e quem o utilizou.","Sua história incorpora destreza, criação e práticas sociais, indo além da classificação por estilo.","A relaciona o patrimônio às habilidades artísticas e culturais dos sujeitos."],"alternatives":{"A":"Criadores e usuárias imprimem conhecimentos, técnicas e experiências ao objeto.","B":"O texto não caracteriza todos os fabricantes como mestres religiosos ou pedagogos.","C":"O foco são sujeitos ligados à vida do objeto, não a formação dos expositores.","D":"Preservação arquitetônica não explica a história social narrada pelo móvel.","E":"Venda aparece, mas a memória não se reduz a competências financeiras de comerciantes."},"takeaway":"Um objeto museológico pode revelar relações sociais de produção e uso, não apenas material e estilo.","key":"humanas:H791","area":"humanas","year":2022,"number":79,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A retórica liga formação intelectual e vida pública","steps":["O texto vincula formas de racionalidade às condições da pólis.","Na cidade, o debate e a persuasão ganham relevância para a atuação política.","Os sofistas, professores de retórica, tornam clara essa ligação: C. Não significa que tenham fundado a escola de Mileto."],"alternatives":{"A":"O ideal epicurista de vida feliz não é o vínculo específico entre formação discursiva e cidade.","B":"O domínio estoico diante de infortúnios não explica diretamente a centralidade da retórica.","C":"Ensinar argumentação e persuasão conecta a formação sofística às práticas públicas da pólis.","D":"A organização peripatética do ensino não é a categoria pedida pelo item.","E":"Rapsodos transmitem narrativas míticas; não são o grupo de ensino retórico referido."},"takeaway":"Não comprima toda a filosofia antiga num mesmo momento: o item aproxima processos, não datas idênticas.","key":"humanas:H645","area":"humanas","year":2022,"number":80,"answer":"C","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Controlar insumos também controla a imprensa","steps":["O órgão coordena a relação entre imprensa e governo.","A autorização de devoluções vinculadas ao papel depende de julgamento sobre utilidade dos jornais.","Esse poder administrativo pode pressionar publicações e restringir expressão: D, no contexto autoritário do Estado Novo."],"alternatives":{"A":"O controle governamental das condições de publicação não promove pluralidade por si.","B":"O trecho trata diretamente da imprensa, não da venda de cultura popular.","C":"Sindicatos não são o alvo das competências selecionadas no decreto.","D":"Submeter jornais à avaliação do governo permite limitar circulação e liberdade de expressão.","E":"O texto não determina transferir empresas públicas de comunicação a particulares."},"takeaway":"Censura pode operar por coerção administrativa e econômica, além da proibição explícita de uma frase.","key":"humanas:H105","area":"humanas","year":2022,"number":81,"answer":"D","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Rochas ígneas podem concentrar minerais metálicos","steps":["O mapa identifica afloramentos e formações de origem ígnea.","Processos de cristalização e diferenciação magmática podem concentrar certos minerais metálicos.","B reconhece esse potencial, sem afirmar que toda rocha ígnea contenha jazida explorável."],"alternatives":{"A":"A presença de rocha antiga não implica terremotos periódicos como recurso principal.","B":"Processos associados ao magmatismo favorecem a ocorrência de algumas jazidas metálicas.","C":"Combustíveis fósseis se associam principalmente a bacias e rochas sedimentares.","D":"O mapa não representa bacias de aquíferos sedimentares profundos.","E":"Metamorfismo é transformação de rochas; não define as formações ígneas mapeadas."},"takeaway":"Potencial geológico de ocorrência não equivale a reserva conhecida ou exploração economicamente viável.","key":"humanas:H527","area":"humanas","year":2022,"number":82,"answer":"B","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Sem nacionalidade reconhecida, há apatridia","steps":["Na situação narrada, as crianças não conseguem reconhecimento pelo país onde nasceram.","Também não conseguem o reconhecimento pelo país de origem dos pais.","B identifica apatridia: ausência de nacionalidade reconhecida por um Estado, não necessariamente fuga ou crime."],"alternatives":{"A":"Exílio implica afastamento de um país, não define ausência de nacionalidade.","B":"A condição apresentada é não obter reconhecimento de nacionalidade pelos Estados envolvidos.","C":"Foragido é quem foge de perseguição ou ação da justiça, o que não foi narrado.","D":"Refúgio e apatridia podem coexistir, mas o fato central é a falta de nacionalidade.","E":"Irregularidade migratória não é sinônimo de não possuir nacionalidade."},"takeaway":"Diferencie nacionalidade, registro civil, situação migratória e condição de refugiado.","key":"humanas:H363","area":"humanas","year":2022,"number":83,"answer":"B","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ver e criar imagens também produz conhecimento","steps":["Merleau-Ponty atribui às artes um papel no reaprender a ver.","Deleuze reconhece pensamento na construção de imagens cinematográficas.","C considera o olhar uma experiência cognitiva, sem subordinar a arte a mero auxílio de uma razão externa."],"alternatives":{"A":"Os trechos não definem o belo como entidade transcendental.","B":"O problema não se limita ao juízo individual de gostar ou não de uma obra.","C":"Percepção e imagens são apresentadas como modos de conhecer e pensar.","D":"A arte não aparece apenas como ilustração auxiliar de conceitos já prontos.","E":"A formulação é abstrata e não identifica o papel específico da experiência sensível."},"takeaway":"Experiência estética pode produzir perguntas e conhecimento, não apenas decorar uma explicação conceitual.","key":"humanas:H703","area":"humanas","year":2022,"number":84,"answer":"C","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O ritual organiza até o comportamento do público","steps":["O primeiro texto regula circulação, objetos e atos dos espectadores.","O segundo explica que gestos, lugares e palavras do auto de fé são previamente fixados.","D mostra a capacidade de produzir padrões de conduta, não a liberação irrestrita de violência popular."],"alternatives":{"A":"A existência de regras não significa que o rito deixe de ser uma punição coercitiva.","B":"O primeiro texto proíbe agressões espontâneas aos réus, em vez de simplesmente incentivá-las.","C":"O ritual exerce disciplina e não tem como finalidade criticá-la.","D":"O controle de gestos, trajetos e atitudes estabelece padrões para participantes e espectadores.","E":"O rito combate aquilo que a instituição chama heresia, não organiza seu culto."},"takeaway":"Controle ritual pode disciplinar tanto os punidos quanto quem assiste à punição.","key":"humanas:H194","area":"humanas","year":2022,"number":85,"answer":"D","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Arché é uma questão sobre origem e composição do cosmos","steps":["Empédocles propõe quatro elementos permanentes.","Amor e Ódio explicam mistura, separação e mudança dos seres.","C reconhece a discussão cosmogônica sobre princípios do mundo, não uma simples psicologia das paixões humanas."],"alternatives":{"A":"Investigar filosoficamente é amplo; não define o tema específico da arché.","B":"O trecho explica a composição e mudança da natureza, sem abandonar o mundo sensível.","C":"Elementos e forças são mobilizados para explicar a constituição e transformação do cosmos.","D":"Amor e Ódio nomeiam princípios cósmicos, não apenas emoções de indivíduos.","E":"Usar esses nomes não reduz a proposta a uma narrativa mitológica tradicional."},"takeaway":"Leia o sentido técnico de palavras comuns: Amor e Ódio funcionam como princípios cosmológicos no trecho.","key":"humanas:H646","area":"humanas","year":2022,"number":86,"answer":"C","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O êxodo rural alimenta a concentração metropolitana","steps":["A macrocefalia reúne atividades econômicas e fluxos populacionais em poucas metrópoles.","A saída de pessoas do campo em direção às cidades pode intensificar esse crescimento concentrado.","B identifica esse fator, sem afirmar que a migração seja a única causa dos problemas urbanos."],"alternatives":{"A":"Limitar a área ocupada não é o fluxo populacional que explica a concentração.","B":"O êxodo rural redireciona população para centros urbanos de atração econômica.","C":"O risco habitacional é sobretudo uma consequência apontada do crescimento desordenado.","D":"Problemas de transporte não são o fator migratório central solicitado.","E":"Fecundidade gera crescimento natural, diferente do redirecionamento espacial de população destacado."},"takeaway":"Separe fatores de atração e deslocamento de suas consequências sobre emprego, moradia e infraestrutura.","key":"humanas:H396","area":"humanas","year":2022,"number":87,"answer":"B","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A filosofia ajuda a lidar com o que não se controla","steps":["Basso mantém firmeza diante do declínio corporal e da morte.","A serenidade decorre do trabalho filosófico sobre juízos e reações afetivas.","E identifica moderação das paixões, não desejo de sofrer ou obrigação de nunca sentir tristeza."],"alternatives":{"A":"Não se descreve uma disputa de argumentos entre participantes.","B":"Rejeitar toda convenção não é o motivo da serenidade do personagem.","C":"O texto atribui o efeito à filosofia, não a uma experiência religiosa específica.","D":"O sofrimento não é valorizado por si; busca-se não ser dominado por ele.","E":"O exercício filosófico permite regular paixões e enfrentar adversidades com firmeza."},"takeaway":"Estoicismo não é glorificação da dor nem ausência mecânica de emoções: envolve trabalhar juízos e ações.","key":"humanas:H647","area":"humanas","year":2022,"number":88,"answer":"E","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Diferentes povos produziram conhecimentos próprios","steps":["O texto enumera organização social, astronomia, matemática e práticas cirúrgicas.","Esse repertório mostra diversidade de saberes anteriores à conquista europeia.","C é a síntese abrangente. A afirmação de prioridade absoluta sobre o zero no texto não é necessária para reconhecer esse legado e não deve ser generalizada como cronologia comprovada."],"alternatives":{"A":"Os saberes citados antecedem a imposição da matriz cristã colonial.","B":"Não se trata principalmente de armas obtidas por pilhagem em guerras coloniais.","C":"Astronomia, matemática, técnicas e organização compõem heranças culturais desses povos.","D":"O texto valoriza desenvolvimentos próprios, não costumes copiados de modelos estrangeiros.","E":"Medicina é apenas parte do legado; a alternativa também projeta uma categoria científica sem abranger o conjunto."},"takeaway":"Evite hierarquizar civilizações por um único indicador e prefira a alternativa que abrange todos os exemplos.","key":"humanas:H195","area":"humanas","year":2022,"number":89,"answer":"C","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Recursos naturais sustentam um modo de fazer e viver","steps":["Argila, madeira e casca de mangue integram a produção das panelas.","O saber transmitido entre gerações articula técnica, identidade e relações com o ambiente.","A identifica manutenção de modos de vida, sem exigir que a prática permaneça totalmente sem mudanças."],"alternatives":{"A":"A seleção e transformação dos recursos reproduzem um saber-fazer e a vida social ligada a ele.","B":"O texto não descreve a conservação de plantações agrícolas.","C":"Atualizar modelos gerenciais não é a característica tradicional apresentada.","D":"Vender produtos pode ocorrer, mas a relação central envolve continuidade cultural e recursos locais.","E":"Há etapas técnicas, mas a especialização isolada não explica o vínculo com o modo de vida."},"takeaway":"Tradição pode persistir incorporando adaptações, como o uso de sobras de madeira da construção civil.","key":"humanas:H792","area":"humanas","year":2022,"number":90,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2022.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
